/**
 * Capacity and diurnal curves (kW) by node profile.
 *
 * Readings are a pure function of (node nonce, timestamp): the same node at the
 * same instant always produces the same target, so history generated by the
 * backfill script lines up exactly with what the live simulator continues.
 *
 * Every node gets its own "nonce" (derived from its owner, its id and an optional
 * SIMULATOR_NONCE_SALT). The nonce drives per-node traits (capacity, peak shift,
 * load pattern) and per-node weather, so different users see different curves.
 * Weather also has a shared regional component, so nodes on the same grid still
 * have correlated cloudy or windy days, like a real region.
 */

const CAPACITY_KW = {
  solar: { generate: 48, consume: 2 },
  wind: { generate: 55, consume: 3 },
  home: { generate: 4, consume: 28 },
  industry: { generate: 12, consume: 85 },
  other: { generate: 20, consume: 20 },
};

const TWO_PI = Math.PI * 2;
const DAY_MS = 24 * 60 * 60 * 1000;

const clamp = (min, max, value) => Math.min(max, Math.max(min, value));

/* ------------------------------------------------------------------ */
/* Deterministic randomness                                            */
/* ------------------------------------------------------------------ */

/** 32-bit FNV-1a string hash. */
const hash32 = (str) => {
  let h = 2166136261;
  const s = String(str);
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
};

/** Deterministic value in [0, 1) for a key. */
const unit = (key) => hash32(key) / 4294967296;

/** Deterministic value in [-1, 1) for a key. */
const signed = (key) => unit(key) * 2 - 1;

/* ------------------------------------------------------------------ */
/* Local clock (fixed offset so every machine agrees)                  */
/* ------------------------------------------------------------------ */

/**
 * The curves peak at "local" solar noon. A fixed offset (not the host's timezone)
 * keeps the backfill and the live simulator consistent whichever machine runs
 * them. Default +330 minutes (IST); override with SIMULATOR_TZ_OFFSET_MINUTES.
 */
const getTzOffsetMinutes = () => {
  const parsed = parseInt(process.env.SIMULATOR_TZ_OFFSET_MINUTES ?? '330', 10);
  return Number.isFinite(parsed) ? parsed : 330;
};

const localClock = (at) => {
  const shifted = new Date(at.getTime() + getTzOffsetMinutes() * 60 * 1000);
  const hour = shifted.getUTCHours();
  const minute = shifted.getUTCMinutes();
  const startOfYear = Date.UTC(shifted.getUTCFullYear(), 0, 0);
  return {
    hour,
    minute,
    t: hour + minute / 60,
    dayOfWeek: shifted.getUTCDay(),
    dayOfYear: Math.floor((shifted.getTime() - startOfYear) / DAY_MS),
    dayKey: shifted.toISOString().slice(0, 10),
  };
};

/* ------------------------------------------------------------------ */
/* Per-node nonce and traits                                           */
/* ------------------------------------------------------------------ */

/**
 * Stable identity string for a node. Different owners / nodes / salts give
 * different nonces and therefore different simulated readings.
 */
const nodeNonce = (node) =>
  [node.simNonce, node.userId, node._id || node.nodeId || node.name || 'node', process.env.SIMULATOR_NONCE_SALT]
    .filter((part) => part !== undefined && part !== null && part !== '')
    .map(String)
    .join('|');

const traitCache = new Map();

const getTraits = (nonce) => {
  let traits = traitCache.get(nonce);
  if (traits) return traits;
  traits = {
    capacityScale: 0.75 + unit(`${nonce}:cap`) * 0.55, // 0.75 .. 1.30
    loadScale: 0.8 + unit(`${nonce}:load`) * 0.5, // 0.80 .. 1.30
    solarShiftHours: signed(`${nonce}:shift`) * 1.25, // panel orientation
    solarWidthScale: 0.9 + unit(`${nonce}:width`) * 0.25,
    loadShiftHours: signed(`${nonce}:loadshift`) * 0.8, // household routine
    windBias: signed(`${nonce}:wind`) * 0.12,
    phase: unit(`${nonce}:phase`) * TWO_PI,
  };
  if (traitCache.size > 5000) traitCache.clear();
  traitCache.set(nonce, traits);
  return traits;
};

/** Legacy 0..1 seed kept for API compatibility. */
const hashSeed = (str) => (hash32(str) % 10000) / 10000;

/* ------------------------------------------------------------------ */
/* Curves                                                              */
/* ------------------------------------------------------------------ */

/** Gaussian-ish solar curve: 0 at night, peak near solar noon. */
const solarIrradiance = (t, peakHour = 13, width = 3.2) => {
  if (t < 4.5 || t >= 21.5) return 0;
  const x = (t - peakHour) / width;
  const value = Math.exp(-0.5 * x * x);
  return value < 0.03 ? 0 : value;
};

/** Longer days in summer, shorter in winter (northern hemisphere). */
const seasonalSolarFactor = (dayOfYear) => 0.88 + 0.12 * Math.cos((TWO_PI * (dayOfYear - 172)) / 365);

/** Cloud cover for the day: shared regional weather blended with local weather. */
const solarWeather = (nonce, traits, clock) => {
  const regional = unit(`region|${clock.dayKey}|sun`);
  const local = unit(`${nonce}|${clock.dayKey}|sun`);
  const cloudiness = 0.6 * regional + 0.4 * local; // 0 clear .. 1 overcast
  const dayFactor = 1 - 0.55 * cloudiness ** 1.3;
  const slow = Math.sin(clock.t * 0.9 + traits.phase) * 0.08 * cloudiness;
  const fast = signed(`${nonce}|${clock.dayKey}|${Math.floor(clock.t * 6)}`) * 0.07 * (0.3 + cloudiness);
  return clamp(0.25, 1.05, dayFactor + slow + fast);
};

/** Wind: day-level mean (regional + local) with diurnal shift and gusts. */
const windAvailability = (t, nodeSeed = 0, dayMean = 0.55) => {
  const diurnal = 0.12 * Math.sin(((t - 4) * Math.PI) / 12);
  const gust = 0.18 * Math.sin(t * 0.9 + nodeSeed * 1.7);
  const turbulence = 0.08 * Math.sin(t * 2.3 + nodeSeed);
  return clamp(0.08, 1, dayMean + diurnal + gust + turbulence);
};

const windDayMean = (nonce, traits, clock) => {
  const regional = unit(`region|${clock.dayKey}|wind`);
  const local = unit(`${nonce}|${clock.dayKey}|wind`);
  return clamp(0.2, 0.85, 0.22 + 0.55 * (0.6 * regional + 0.4 * local) + traits.windBias);
};

/** Residential load: morning and evening peaks. */
const homeLoadFactor = (t, shift = 0) => {
  const morning = Math.exp(-0.5 * ((t - (8 + shift)) / 1.8) ** 2);
  const evening = Math.exp(-0.5 * ((t - (19 + shift)) / 2.2) ** 2);
  const base = 0.22;
  return clamp(0.1, 1, base + morning * 0.55 + evening * 0.65);
};

/** Industrial: weekday daytime, lower on weekends. */
const industryLoadFactor = (t, dayOfWeek) => {
  const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
  if (t < 6 || t >= 22) return isWeekend ? 0.08 : 0.12;
  const workday = Math.exp(-0.5 * ((t - 14) / 4) ** 2);
  const scale = isWeekend ? 0.35 : 1;
  return clamp(0.1, 1, (0.35 + workday * 0.55) * scale);
};

/** Day-to-day variation in demand (weekends slightly higher for homes). */
const dayLoadVariation = (nonce, clock, weekendBoost) => {
  const weekend = clock.dayOfWeek === 0 || clock.dayOfWeek === 6;
  return 1 + 0.08 * signed(`${nonce}|${clock.dayKey}|load`) + (weekend ? weekendBoost : 0);
};

/* ------------------------------------------------------------------ */
/* Capacity                                                            */
/* ------------------------------------------------------------------ */

const resolveBaseCapacity = (sourceType, overrides) => {
  if (overrides && overrides[sourceType]) {
    return {
      generate: overrides[sourceType].capacityGenerateKw,
      consume: overrides[sourceType].capacityConsumeKw,
    };
  }
  return CAPACITY_KW[sourceType] || CAPACITY_KW.other;
};

const getCapacity = (sourceType, nodeType, overrides) => {
  const base = resolveBaseCapacity(sourceType, overrides);
  if (nodeType === 'consumer') {
    return { generate: base.generate * 0.15, consume: base.consume };
  }
  if (nodeType === 'producer') {
    return { generate: base.generate, consume: base.consume * 0.2 };
  }
  return base;
};

/* ------------------------------------------------------------------ */
/* Targets                                                             */
/* ------------------------------------------------------------------ */

/**
 * Target kW before smoothing (not yet noised). Deterministic for a given node
 * and timestamp.
 * @param {object} node - { nodeType, sourceType, status, userId?, _id|nodeId }
 * @param {Date} at
 * @param {object} [options]
 * @param {object} [options.capacityOverrides] - DB-backed capacity overrides keyed by sourceType
 */
const computeTargets = (node, at = new Date(), options = {}) => {
  const sourceType = node.sourceType || 'other';
  const nodeType = node.nodeType || 'producer';
  const nonce = nodeNonce(node);
  const traits = getTraits(nonce);
  const clock = localClock(at);
  const baseCapacity = getCapacity(sourceType, nodeType, options.capacityOverrides);
  const capacity = {
    generate: baseCapacity.generate * traits.capacityScale,
    consume: baseCapacity.consume * traits.loadScale,
  };

  if (node.status === 'inactive') {
    return { energyGenerated: 0, energyConsumed: 0 };
  }

  if (node.status === 'maintenance') {
    return {
      energyGenerated: capacity.generate * 0.02,
      energyConsumed: capacity.consume * 0.15,
    };
  }

  const sun = () =>
    solarIrradiance(clock.t - traits.solarShiftHours, 13, 3.2 * traits.solarWidthScale) *
    seasonalSolarFactor(clock.dayOfYear) *
    solarWeather(nonce, traits, clock);
  const home = () => homeLoadFactor(clock.t, traits.loadShiftHours) * dayLoadVariation(nonce, clock, 0.08);

  let genTarget = 0;
  let conTarget = 0;

  switch (sourceType) {
    case 'solar':
      genTarget = capacity.generate * sun();
      conTarget = capacity.consume * (0.3 + home() * 0.2);
      break;
    case 'wind': {
      const wind = windAvailability(clock.t, traits.phase, windDayMean(nonce, traits, clock));
      genTarget = capacity.generate * wind;
      conTarget = capacity.consume * (0.25 + home() * 0.15);
      break;
    }
    case 'home':
      genTarget = capacity.generate * sun() * 0.35;
      conTarget = capacity.consume * home();
      break;
    case 'industry':
      genTarget = capacity.generate * sun() * 0.2;
      conTarget = capacity.consume * industryLoadFactor(clock.t, clock.dayOfWeek) * dayLoadVariation(nonce, clock, 0);
      break;
    default: {
      const wind = windAvailability(clock.t, traits.phase, windDayMean(nonce, traits, clock));
      genTarget = (capacity.generate * 0.4 * (sun() + wind)) / 2;
      conTarget = capacity.consume * home();
    }
  }

  if (nodeType === 'consumer') {
    genTarget *= 0.1;
  } else if (nodeType === 'producer') {
    conTarget *= 0.25;
  }

  return {
    energyGenerated: Math.max(0, genTarget),
    energyConsumed: Math.max(0, conTarget),
  };
};

/**
 * Small deterministic measurement noise for a node and minute, used by the
 * backfill so history looks like real metering, not a perfectly smooth curve.
 * Returns multipliers around 1.
 */
const deterministicNoise = (node, at) => {
  const nonce = nodeNonce(node);
  const minute = Math.floor(at.getTime() / 60000);
  return {
    generated: 1 + signed(`${nonce}|ng|${minute}`) * 0.05,
    consumed: 1 + signed(`${nonce}|nc|${minute}`) * 0.04,
  };
};

/**
 * Hourly normalised factor (0..~1) for a source type — used to render an
 * accurate schedule preview in the admin UI without duplicating curve math.
 * Uses a neutral node and a clear-sky, average day.
 */
const previewFactors = (sourceType) => {
  const out = [];
  for (let hour = 0; hour < 24; hour += 1) {
    let factor = 0;
    switch (sourceType) {
      case 'solar':
        factor = solarIrradiance(hour);
        break;
      case 'wind':
        factor = windAvailability(hour, 0, 0.55);
        break;
      case 'home':
        factor = homeLoadFactor(hour);
        break;
      case 'industry':
        factor = industryLoadFactor(hour, 1);
        break;
      default:
        factor = (solarIrradiance(hour) + windAvailability(hour, 0, 0.55)) / 2;
    }
    out.push({ hour, factor: Math.round(Math.max(0, factor) * 1000) / 1000 });
  }
  return out;
};

module.exports = {
  CAPACITY_KW,
  SOURCE_TYPES: ['solar', 'wind', 'home', 'industry', 'other'],
  computeTargets,
  deterministicNoise,
  nodeNonce,
  getCapacity,
  resolveBaseCapacity,
  hashSeed,
  previewFactors,
};
